#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [0.01342949, 0.019580655000000002, -0.388554465], 'basis': [[0.0, -0.0, 1.0], [0.0, 1.0, 0.0], [-1.0, 0.0, 0.0]], 'axis': [1.0, 0.0, 0.0], 'zmin': -0.013347600000000001, 'zmax': 0.0133476, 'profiles': [{'outer': [[-0.0072130049999999946, 0.001240214999999996], [-0.005130844409576595, 0.002122620174946558], [-0.00227902499999999, 0.012818974999999996], [-0.0019971359150373702, 0.013132115382210641], [-0.001998370808329792, 0.013292812996271379], [-0.005407885000000001, 0.015490375], [-0.0057391649999999905, 0.015607024999999997], [-0.0077654249999999925, 0.015792294999999998], [-0.00795290500000001, 0.016047384999999997], [-0.007993324999999996, 0.036102085], [-0.007847816529698527, 0.03610846038948058], [-0.007991445000000041, 0.036108575], [-0.008074475000000025, 0.076222185], [-0.007885764999999989, 0.076461155], [-0.0012121650000000428, 0.07661623499999999], [0.0028816649999999777, 0.076843015], [0.0032487449999999973, 0.076811055], [0.005412205000000003, 0.07629433499999999], [0.005590874999999995, 0.076012735], [0.005674644999999978, 0.055038384999999995], [0.00560400534157757, 0.055038020713972985], [0.00567759499999998, 0.055037185], [0.005764324999999959, 0.034064475], [0.005670179970795064, 0.03406455011321767], [0.005763254999999967, 0.034061265], [0.005851555000000008, 0.013094834999999999], [0.005658614999999978, 0.012837274999999995], [0.004182324999999987, 0.012727594999999994], [0.004153378598987838, 0.012645902446514297], [0.004335124999999995, 0.012345064999999995], [0.004110954999999972, 0.012368594999999996], [0.0019957049999999588, 0.014299725], [0.001610475, 0.014478954999999995], [-0.002164140270052545, 0.012867221268091682], [0.0016110749999999618, 0.014475984999999997], [0.0019945650000000037, 0.014296734999999998], [0.004110174999999994, 0.012366244999999998], [0.00433351500000001, 0.012344744999999997], [0.005392931621320255, 0.001645787284409422], [0.006366304999999961, 0.0012402249999999976], [0.009181934999999974, -0.005531605000000002], [0.006366304999999961, -0.012339035000000002], [0.004087440622541894, -0.01329362094557175], [0.0056408249999999605, -0.015089215000000003], [0.005939974999999986, -0.015250565000000002], [0.009485384999999957, -0.015687625000000004], [0.009668334999999972, -0.015950625000000003], [0.009788324999999987, -0.035777375], [0.009613799844706243, -0.0357941687686197], [0.00978722500000001, -0.035781935], [0.009906935000000006, -0.055614865], [0.008066412492533072, -0.05570489806992074], [0.009908634999999999, -0.055614815000000005], [0.010028614999999963, -0.075441565], [0.00983141500000001, -0.075717725], [0.004332795, -0.07660054499999999], [0.002080044999999975, -0.076843015], [0.0017041449999999903, -0.076837575], [-0.0022793850000000226, -0.076380395], [-0.0038584850000000226, -0.076378365], [-0.00405503500000004, -0.07613910500000001], [-0.004552855000000022, -0.034108865], [-0.004359675000000007, -0.034113035], [-0.004142685943234651, -0.03411019514554825], [-0.004553004999999999, -0.034105835], [-0.00480097252155922, -0.013358919456442709], [-0.00721297500000001, -0.012339045000000003], [-0.010028615000000018, -0.005531605000000002]], 'holes': [[[-0.001696267012793957, 0.05543528153815296], [-0.0013278250000000047, 0.055405205], [-8.086527400243075e-05, 0.05570615198185572], [-0.0013267550000000128, 0.05540848499999999]], [[0.000687906490097579, -0.0559005525282169], [0.0013970649999999751, -0.055871775000000005], [0.001818704999999976, -0.055808765], [0.0026109073750079917, -0.05553401529343668], [0.0018172149999999831, -0.055807235000000004]], [[-0.0018269250000000348, 0.013348684999999999], [-0.0015882349999999934, 0.013495765], [-0.0020010249999999896, 0.013638205]], [[-0.0019946684839810373, 0.013133841274541544], [-0.001899105000000012, 0.013200684999999997], [-0.0017098301945043266, 0.013281406164841433], [-0.0018269250000000348, 0.013348684999999999]], [[0.003330104999999972, -0.033962085], [0.003753744999999975, -0.034115095], [0.004794123464225414, -0.03480089680974456], [0.0037562449999999914, -0.034111565], [0.0033289349999999773, -0.033960805000000004], [0.002562379904014957, -0.03442275606359196]], [[0.005113282541412396, -0.05547102416257411], [0.004044734999999966, -0.055229805], [0.0037681333792171476, -0.055200539578265956], [0.0040436849999999636, -0.055234525]], [[0.00640796499999996, -0.03564566500000001], [0.006342078284957848, -0.03563753879921405], [0.008238475579325766, -0.035732881018044296]], [[0.0031667549999999656, 0.055485435], [0.0034477520555875876, 0.055385585666697046], [0.0019442744715467465, 0.05577577984453519]]]}], 'simplify_tolerance': 3.0737206000000004e-05, 'sketch_entity_count': 127}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
